using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly FakeProvider provider = new();

    private HttpPaymentGateway Gateway() => new(new HttpClient { BaseAddress = provider.BaseAddress });

    private Task<AuthorizationOutcome> Authorize(string reference = "ORD-7", decimal amount = 12.5m, string currency = "eur") =>
        Gateway().AuthorizeAsync(reference, new Money(amount, currency), CancellationToken.None);

    [Fact]
    public async Task The_request_is_a_json_post_to_the_authorizations_endpoint()
    {
        provider.Respond(200, """{"status":"approved"}""");

        await Authorize();

        var received = Assert.Single(provider.Requests);
        Assert.Equal("POST", received.Method);
        Assert.Equal("/v1/authorizations", received.Path);
        Assert.StartsWith("application/json", received.ContentType);
        using var json = JsonDocument.Parse(received.Body);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_status_is_read_as_approved()
    {
        provider.Respond(200, """{"status":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_status_is_read_as_declined()
    {
        provider.Respond(200, """{"status":"declined"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        provider.Respond(200, """{"id":"auth_1","status":"approved","extra":{"a":1}}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task An_unknown_status_is_never_treated_as_approved()
    {
        provider.Respond(200, """{"status":"pending"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task An_answer_without_a_status_is_never_treated_as_approved()
    {
        provider.Respond(200, "{}");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_402_refusal_is_a_decline()
    {
        provider.Respond(402, """{"error":"card_refused"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_error_statuses_surface_as_failures_not_declines(int status)
    {
        provider.Respond(status, """{"error":"nope"}""");

        var error = await Assert.ThrowsAsync<HttpRequestException>(() => Authorize());
        Assert.Equal((HttpStatusCode)status, error.StatusCode);
    }

    [Fact]
    public async Task A_body_that_is_not_json_surfaces_as_a_failure()
    {
        provider.Respond(200, "<html>oops</html>");

        await Assert.ThrowsAnyAsync<JsonException>(() => Authorize());
    }

    public void Dispose() => provider.Dispose();

    private sealed record Received(string Method, string Path, string? ContentType, string Body);

    private sealed class FakeProvider : IDisposable
    {
        private readonly HttpListener listener = new();
        private readonly List<Received> requests = [];
        private int status = 200;
        private string body = "{}";

        public FakeProvider()
        {
            // Retry on port collisions between parallel test runs.
            for (var attempt = 0; ; attempt++)
            {
                var port = Random.Shared.Next(20000, 60000);
                var candidate = new HttpListener();
                candidate.Prefixes.Add($"http://127.0.0.1:{port}/");
                try
                {
                    candidate.Start();
                    listener = candidate;
                    BaseAddress = new Uri($"http://127.0.0.1:{port}");
                    break;
                }
                catch (HttpListenerException) when (attempt < 20) { candidate.Close(); }
            }
            _ = Task.Run(Loop);
        }

        public Uri BaseAddress { get; }

        public IReadOnlyList<Received> Requests { get { lock (requests) return [.. requests]; } }

        public void Respond(int statusCode, string json) { status = statusCode; body = json; }

        private async Task Loop()
        {
            while (listener.IsListening)
            {
                HttpListenerContext context;
                try { context = await listener.GetContextAsync(); }
                catch (Exception) { return; }

                var request = context.Request;
                using var reader = new StreamReader(request.InputStream, Encoding.UTF8);
                var text = await reader.ReadToEndAsync();
                lock (requests) requests.Add(new Received(request.HttpMethod, request.Url!.AbsolutePath, request.ContentType, text));

                var bytes = Encoding.UTF8.GetBytes(body);
                context.Response.StatusCode = status;
                context.Response.ContentType = "application/json";
                context.Response.ContentLength64 = bytes.Length;
                await context.Response.OutputStream.WriteAsync(bytes);
                context.Response.Close();
            }
        }

        public void Dispose() => listener.Close();
    }
}
